export function createCourseUI({api,esc,heading,toast,modal,getState,isCurrent,refresh}) {
 const $=s=>document.querySelector(s),link=key=>'#practice/'+encodeURIComponent(key);
 const contextualLink=(key,context)=>link(key)+(context.returnNode?'?from='+encodeURIComponent(context.returnNode):'');
 const certificate=(kind,id)=>'/api/certificates/'+kind+'/'+encodeURIComponent(id);
 const progress=(done,total)=>`<progress max="${total||1}" value="${done}" aria-label="${done} of ${total} activities complete"></progress>`;
 const statusLabel=s=>s?.status==='correct'?'✓ Correct':s?.status==='tutor_met'?'✓ Tutor criteria met':s?.status==='reviewed'?'✓ Reviewed by you':s?.attempts?'◐ In progress':'○ Not started';
 const status=key=>getState().learning?.exercise_status[key];
 const moduleFor=key=>getState().learning?.modules.find(m=>m.exercise_keys.includes(key));
 function nextFor(key){
  const l=getState().learning,m=moduleFor(key);if(!m)return null;
  const c=l.courses.find(c=>c.id===m.course_id),next=m.next_key||c.modules.find(mm=>!mm.is_complete)?.next_key||l.recommended?.exercise_key;
  return getState().exercises.find(e=>e.key===next&&next!==key)||null;
 }
 function overview(l){const s=l.summary;return `<div class="learning-stats"><div><strong>${s.points}</strong><span>practice points</span></div><div><strong>${s.completed} <small>/ ${s.total}</small></strong><span>activities complete</span></div><div><strong>${s.modules_complete} <small>/ ${l.modules.length}</small></strong><span>modules complete</span></div><div><strong>${s.selected_paragraphs} <small>/ ${s.writing_targets}</small></strong><span>WISE paragraphs selected</span></div></div>`}
 function recommendation(l){let key;try{key=localStorage.getItem('awl-practice-resume')}catch{}const m=key?l.modules.find(m=>m.exercise_keys.includes(key)):null,c=m?l.courses.find(c=>c.id===m.course_id):null,next=m&&(m.next_key?m:c.modules.find(x=>x.next_key));const r=next?{module_id:next.id,exercise_key:next.next_key,title:next.title,reason:'Continue the course you chose. Your WISE writing has its own bookmark.'}:l.recommended;return r?`<section class="card focus-card"><span class="tag">YOUR NEXT STEP</span><h2>${esc(r.title)}</h2><p>${esc(r.reason)}</p><div class="actions"><a class="btn" href="${link(r.exercise_key)}">Continue learning →</a><a class="btn secondary" href="#courses/${encodeURIComponent(r.module_id)}">See the module</a><a class="btn quiet" href="#courses">Choose a different course</a></div></section>`:'<section class="card"><h2>Your current course activities are complete.</h2><p>Return to a difficult skill without the examples, or continue revising your WISE manuscript.</p><a class="btn" href="#paper">Open my paper</a></section>'}
 function advancedStart(l){const courses=l.courses.filter(c=>c.kind==='advanced');if(!courses.length)return '';const total=courses.reduce((n,c)=>n+c.total,0),done=courses.reduce((n,c)=>n+c.completed,0),core=Object.entries(l.exercise_status).filter(([k])=>k.startsWith('AWL-EN-CORE@'));return `<section class="card advanced-callout"><span class="tag">YOUR NEXT CHALLENGE</span><h2>From choosing a word to defending your wording.</h2><p><strong>${core.filter(([,s])=>s.completed).length}/${core.length} core English activities complete.</strong> Your completed work stays recorded. The new advanced path adds ${total} activities across 32 modules, with ${done} already complete.</p><p>Diagnose → write from evidence → judge a revision → write a concise brief. Each module uses three cases, including a case outside your research area.</p><div class="actions"><a class="btn" href="#courses/advanced">Explore advanced English →</a><a class="btn secondary" href="#courses/advanced-argument">Start with argument building</a><a class="btn quiet" href="#phrasebook">Phrasebook for WISE</a></div></section>`}
 function home(){const l=getState().learning;let resume;try{resume=JSON.parse(localStorage.getItem('awl-writing-resume'))}catch{}const writingKey=getState().exercises.some(e=>e.paper_node_id===resume)?resume:'I-01';
  $('#main').innerHTML=heading('See your progress. Know your next step.','Practise the skill, understand the reasoning, then use it in your own paper.')+`<div class="wb-home-intentions"><a class="card" href="#paper/${encodeURIComponent(writingKey)}"><span class="tag">WRITE WISE</span><h2>Continue my argument</h2><p>Return to ${esc(writingKey)}, build its reasoning and write in context.</p></a><a class="card" href="#courses"><span class="tag">PRACTISE ENGLISH</span><h2>Continue my learning</h2><p>Courses, completed activities and your next useful exercise.</p></a></div>`+advancedStart(l)+overview(l)+recommendation(l)+`<div class="grid"><section class="card"><h2>Your completed work counts</h2><p>${l.summary.correct} activities have a correct checked answer. ${l.summary.tutor_met} writing activities met all tutor criteria. ${l.summary.reviewed} have your recorded self-review.</p><p>${l.summary.active_days_last_seven} active days in the last seven days. Return at your own pace; there is no penalty for a break.</p><a class="btn secondary" href="#courses">My courses & achievements</a></section><section class="card"><h2>Build one WISE paragraph</h2><p>Read the argument brief, check its source cards, try a worked example from another subject, and write your own paragraph.</p><a class="btn secondary" href="#paper/I-01">Open the first paragraph brief</a></section></div><p class="tiny">${esc(l.assessment_note)}</p>`;
 }
 function practiceProgress(e){
  const m=moduleFor(e.key);if(!m)return;
  let area=$('#module-progress');if(!area){$('.exercise-body .card-label').insertAdjacentHTML('beforebegin','<section id="module-progress" class="module-progress"></section>');area=$('#module-progress')}
  const s=status(e.key),c=getState().learning.courses.find(c=>c.id===m.course_id);
  area.innerHTML=`<div class="section-row"><a href="#courses/${encodeURIComponent(m.id)}">${esc(c.title)} · ${esc(m.title)}</a><span class="tag ${s?.completed?'green':'neutral'}">${statusLabel(s)}</span></div><div class="module-progress-line">${progress(m.completed,m.total)}<strong>${m.completed}/${m.total}</strong></div>${m.is_complete?`<div class="module-achieved"><strong>✓ Module completed · ${m.total*10} points earned</strong><p>You have a completion record for this module.</p><div class="actions"><a class="btn secondary" href="${certificate('module',m.id)}">Download module certificate</a><a class="btn quiet" href="#courses/${encodeURIComponent(c.id)}">See what comes next</a></div></div>`:`<p class="tiny">Activity ${m.exercise_keys.indexOf(e.key)+1} of ${m.total} · ${m.total-m.completed} still to complete. Each activity earns 10 points once.</p>`}`;
  document.querySelectorAll('[data-exercise-status]').forEach(el=>{const st=status(el.dataset.exerciseStatus);el.textContent=statusLabel(st);el.classList.toggle('complete',!!st?.completed)});
  if(s?.closed&&$('#tutor-feedback .tutor-box')){
   let notice=$('#closed-review-status');if(!notice){$('#tutor-feedback .tutor-box').insertAdjacentHTML('afterbegin','<p id="closed-review-status" class="alert"></p>');notice=$('#closed-review-status')}
   notice.textContent=s.completed?'✓ Activity completed by a correct saved answer. The tutor comments below are additional advice.':'This activity is still in progress. Tutor comments are advice; completion requires a correct checked option or order. Use Check answer to record it.';
   notice.classList.toggle('success',!!s.completed);
  }
 }
 function completionReview(context,isActive){
  if(context.closed)return;
  let area=$('#writing-completion-review');if(!area){$('#answer-feedback').insertAdjacentHTML('afterend','<section id="writing-completion-review" class="learning-support"></section>');area=$('#writing-completion-review')}
  const completed=status(context.e.key);
  if(completed?.completed){
   area.innerHTML=`<div class="alert success"><strong>✓ Activity completed · 10 points recorded</strong><p>${completed.status==='tutor_met'?'Your saved answer met every tutor criterion. No separate self-review is required.':'Your criteria review is recorded.'}</p><small>Completion belongs to the saved version. You can keep revising; points are awarded once.</small></div>`;
   const next=nextFor(context.e.key),evidence=context.session.attempts.find(a=>a.id===completed.evidence_attempt_id);
   if(next){$('#next-exercise-area').innerHTML=`<div class="next-exercise"><button type="button" class="btn" id="next-exercise">Next exercise →</button><span>${esc(next.title)}</span></div>`;$('#next-exercise').onclick=()=>{if(isActive())location.hash=contextualLink(next.key,context)};if(evidence&&evidence.text===$('#answer').value)context.advance={next,text:evidence.text};}
   return;
  }
  const latest=context.session.attempts.at(-1);
  if(area.querySelector('#completion-form'))return; // Keep an in-progress self-review while tutor polling refreshes status.
  area.innerHTML=`<h3>Complete this writing activity</h3><p>You can review your saved answer yourself, even if the tutor is unavailable. A successful tutor review can also complete the activity automatically.</p><button type="button" class="btn secondary" id="review-writing-completion" aria-expanded="false" aria-controls="completion-form" ${!latest?'disabled':''}>Review & mark complete</button>${!latest?'<p class="tiny">Save an attempt first.</p>':''}<div id="completion-form-host"></div>`;
  $('#review-writing-completion').onclick=()=>{
   if(!isActive())return;
   const aa=[...context.session.attempts].reverse(),host=$('#completion-form-host');
   if(host.childElementCount){host.replaceChildren();$('#review-writing-completion').setAttribute('aria-expanded','false');return}
   host.innerHTML=`<section id="completion-form" class="completion-form" aria-label="Review my saved answer"><h3>Review my saved answer</h3><label class="field">Saved version<select id="completion-attempt">${aa.map((a,i)=>`<option value="${esc(a.id)}">${i?'Earlier':'Latest'} saved attempt · ${new Date(a.created).toLocaleString()}</option>`).join('')}</select></label><p class="tiny">Completion applies to this saved version. Changes still in the editor are separate.</p><blockquote class="prose" id="completion-preview"></blockquote><h4>Check the task criteria</h4><ul>${(context.e.criteria||[]).map(c=>`<li>${esc(c)}</li>`).join('')}</ul><label class="checkbox-row"><input type="checkbox" id="completion-confirm">I have checked this saved version against these criteria.</label><label class="field">What did you check or change?<textarea id="completion-reflection" rows="3" minlength="10" maxlength="2500" aria-describedby="completion-help" placeholder="For example: I checked the scope of my claim and the punctuation of however."></textarea></label><p class="tiny" id="completion-help">Add a short note of at least 10 characters, then confirm the checkbox above. This records your own review; it is not a tutor grade.</p><button type="button" class="btn" id="save-completion">Mark complete & save my review</button><p id="completion-status" role="status" aria-live="polite"></p></section>`;
   $('#review-writing-completion').setAttribute('aria-expanded','true');
   const reviewCache='awl-self-review-'+context.e.key;let draft={};try{draft=JSON.parse(localStorage.getItem(reviewCache)||'{}')}catch{}
   if(aa.some(a=>a.id===draft.attempt_id))$('#completion-attempt').value=draft.attempt_id;$('#completion-reflection').value=draft.reflection||'';
   const cacheReview=()=>{if($('#completion-status'))$('#completion-status').textContent='';try{localStorage.setItem(reviewCache,JSON.stringify({attempt_id:$('#completion-attempt').value,reflection:$('#completion-reflection').value}))}catch{}};$('#completion-reflection').oninput=cacheReview;$('#completion-confirm').onchange=()=>{$('#completion-status').textContent=''};
   const preview=()=>{$('#completion-preview').textContent=aa.find(a=>a.id===$('#completion-attempt').value).text;$('#completion-confirm').checked=false;cacheReview()};$('#completion-attempt').onchange=preview;preview();
   $('#completion-form').scrollIntoView({block:'center',behavior:'smooth'});$('#completion-attempt').focus({preventScroll:true});
   $('#save-completion').onclick=async()=>{
    const button=$('#save-completion'),notice=$('#completion-status');
    if(!$('#completion-confirm').checked){notice.textContent='Confirm that you checked the saved answer against the criteria.';$('#completion-confirm').focus();return}
    const reflection=$('#completion-reflection').value.trim();if(reflection.length<10){notice.textContent='Write a short review note of at least 10 characters.';$('#completion-reflection').focus();return}
    button.disabled=true;$('#completion-reflection').readOnly=true;$('#completion-attempt').disabled=true;$('#completion-confirm').disabled=true;notice.textContent='Saving your review…';
    try{await api('/course-completion-review',{attempt_id:$('#completion-attempt').value,reflection});try{localStorage.removeItem(reviewCache)}catch{}await refresh();if(isActive()){practiceProgress(context.e);completionReview(context,isActive)}toast('Activity reviewed · completion points recorded once.')}
    catch(e){if(notice.isConnected)notice.textContent=e.message}finally{if(button.isConnected){button.disabled=false;$('#completion-reflection').readOnly=false;$('#completion-attempt').disabled=false;$('#completion-confirm').disabled=false}}
   };
  };
 }
 async function syncCompletion(context,isActive){
  const learning=await api('/courses');if(!isActive())return;
  getState().learning=learning;practiceProgress(context.e);completionReview(context,isActive);
 }
 async function render(id,serial){
  const l=await api('/courses');if(!isCurrent(serial))return;getState().learning=l;
  const c=l.courses.find(c=>c.id===id),m=l.modules.find(m=>m.id===id);
  if(m){
   const parent=l.courses.find(c=>c.id===m.course_id),next=nextFor(m.exercise_keys.at(-1));
   $('#main').innerHTML=heading(m.title,m.goal,`<a class="btn secondary" href="#courses/${encodeURIComponent(parent.id)}">${esc(parent.title)}</a>`)+`<section class="card"><p><strong>${m.completed}/${m.total} complete · ${m.completed*10} practice points</strong></p>${progress(m.completed,m.total)}<p>Closed activities need a correct saved answer. Open writing completes when all tutor criteria are met with no required correction, or when you record your own criteria review.</p>${m.is_complete?`<div class="actions"><a class="btn" href="${certificate('module',m.id)}">Download module certificate</a>${next?`<a class="btn secondary" href="${link(next.key)}">Continue to the next module →</a>`:''}</div>`:`<a class="btn" href="${link(m.next_key)}">Continue this module →</a>`}</section><section class="card">${m.reading?`<div class="advanced-module-reading"><p><strong>Learn the principle:</strong> ${esc(m.rule)}</p><a href="${esc(m.reading.url)}" target="_blank" rel="noreferrer">${esc(m.reading.title)} · PDF p. ${m.reading.page}–${m.reading.end_page}</a><p class="tiny">Three original cases, revisited with different tasks. Worked examples are available before you answer. Model answers unlock after two saved attempts. Advanced and Stretch describe task demands, not assessed proficiency.</p></div>`:''}<p><a class="btn secondary" href="#obsidian/${encodeURIComponent(m.id)}">Practise this module in Obsidian / on iPad</a></p><h2>The steps in this module</h2><div class="course-exercise-list">${m.exercise_keys.map((key,i)=>{const e=getState().exercises.find(e=>e.key===key),s=l.exercise_status[key];return `<a href="${link(key)}"><span>${i+1}</span><span><strong>${esc(e.title)}</strong><small>${esc(e.difficulty_label)} · ${s.closed?'Checked answer':'Write, revise and review'}</small></span><span class="completion-state ${s.completed?'complete':''}">${statusLabel(s)}</span></a>`}).join('')}</div></section>`;return;
  }
  if(c){
   $('#main').innerHTML=heading(c.title,c.goal,'<a class="btn secondary" href="#courses">All courses</a>')+`<section class="card"><p><strong>${c.completed}/${c.total} activities complete · ${c.percent}%</strong></p>${progress(c.completed,c.total)}${c.is_complete?`<p>✓ Course completed</p><a class="btn" href="${certificate('course',c.id)}">Download course certificate</a>`:`<p>Follow the modules in order, or open the skill you need today. Your progress is shared with Skill practice.</p><a class="btn" href="#courses/${encodeURIComponent(c.next_module)}">Continue course →</a>`}</section><div class="grid catalogue-grid">${c.modules.map((m,i)=>`<a class="card catalogue-card" href="#courses/${encodeURIComponent(m.id)}"><span class="tag ${m.is_complete?'green':'neutral'}">${m.is_complete?'✓ Complete':'Module '+(i+1)}</span><h2>${esc(m.title)}</h2><p>${esc(m.goal)}</p>${progress(m.completed,m.total)}<small>${m.completed}/${m.total} complete · ${m.completed*10} points</small></a>`).join('')}</div>`;return;
  }
  $('#main').innerHTML=(id==='advanced'?heading('Advanced English & Phrasebank','384 activities · 32 modules · write, evaluate and explain your choices.','<a class="btn secondary" href="#phrasebook">Phrasebook for WISE</a>')+`<section class="card advanced-callout"><h2>Choose the skill your next paragraph needs.</h2><p>Each course has four modules. Work through three cases per module: diagnose, draft, judge a revision and write a concise brief. Every task has an outside-field example and a linked book reading.</p><div class="actions"><a class="btn" href="#courses/advanced-argument">Begin with argument building →</a><a class="btn secondary" href="#courses/advanced-phrase-intro">Practise Phrasebank moves</a><a class="btn quiet" href="#courses">All progress & achievements</a></div></section>`:heading('Your learning path','Courses, modules and a visible record of what you have achieved.')+advancedStart(l)+overview(l)+recommendation(l))+`<section class="card"><h2>Choose a course</h2><label class="field">Course focus<select id="course-focus"><option value="">All courses</option><option value="advanced">Advanced English &amp; Phrasebank</option><option value="english">English foundations and writing skills</option><option value="topic">Apply skills to a research topic</option><option value="paper">Build a WISE section</option><option value="custom">My added courses</option></select></label><p class="tiny">${l.courses.length} courses · ${l.modules.length} modules. You can move between them; no course is locked.</p></section><div id="course-list" class="grid catalogue-grid"></div><section class="card"><h2>Milestones</h2><div class="badge-grid">${l.badges.map(b=>`<div class="achievement ${b.earned?'earned':''}"><span>${b.earned?'★':'☆'}</span><strong>${esc(b.title)}</strong><p>${esc(b.description)}</p><small>${b.earned?'Earned':'Still to earn'}</small></div>`).join('')}</div></section><section class="card"><h2>Your overall skill practice</h2><p>These counts show which tasks you have practised successfully or reviewed yourself. They do not measure a CEFR level. A correct guided choice, a positive tutor assessment and your own criteria review are different kinds of practice evidence.</p><div class="table-wrap"><table><thead><tr><th>Skill</th><th>Correct checked tasks</th><th>Tutor criteria met</th><th>Writing reviewed by you</th><th>Practice coverage</th></tr></thead><tbody>${l.skills.map(s=>`<tr><td>${esc(s.title)}</td><td>${s.correct}</td><td>${s.tutor_met}</td><td>${s.reviewed}</td><td>${s.completed}/${s.total}${s.is_complete?`<br><a href="${certificate('skill',s.id)}">Skill completion certificate</a>`:''}</td></tr>`).join('')}</tbody></table></div><p>${l.summary.support_used} completed activities had recorded support before completion. Using examples is part of learning.</p></section><section class="card"><h2>How completion and certificates work</h2><p>${esc(l.completion_rule)}</p><p>Module and course certificates unlock when every activity is complete. They are local self-study records. Download the HTML certificate and use your browser’s Print command to save a PDF.</p><p>${esc(l.assessment_note)}</p></section>`;
  const draw=()=>{const kind=$('#course-focus').value;$('#course-list').innerHTML=l.courses.filter(c=>!kind||c.kind===kind).map(c=>`<a class="card catalogue-card" href="#courses/${encodeURIComponent(c.id)}"><span class="tag ${c.is_complete?'green':'neutral'}">${c.is_complete?'✓ Course complete':c.kind==='advanced'?'Advanced · Stretch':c.kind==='english'?'English skills':c.kind==='topic'?'Research practice':c.kind==='paper'?'Your WISE paper':'Your course'}</span><h2>${esc(c.title)}</h2><p>${esc(c.goal)}</p>${progress(c.completed,c.total)}<small>${c.completed}/${c.total} complete · ${c.modules.length} modules</small></a>`).join('')||'<p>No courses in this category yet.</p>'};$('#course-focus').oninput=draw;if(id==='advanced')$('#course-focus').value='advanced';draw();
 }
 return {home,render,statusLabel,status,moduleFor,nextFor,practiceProgress,completionReview,syncCompletion};
}
